<?php
session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$modules=ttOperationsModuleStates($pdo,(int)$railroad['id']);if(empty($modules['fast_clock']))$_POST['fast_clock_enabled']='0';
if($_SERVER['REQUEST_METHOD']==='POST'){try{ttOperationsRequireCsrf();require_once 'fast_clock_service.php';$pdo->beginTransaction();$number=ttNextScopedNumber($pdo,'operating_sessions','session_number',(int)$railroad['id'],'S',5);$name=substr(trim((string)($_POST['session_name']??'')),0,120);$date=(string)($_POST['operating_date']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Choose a valid operating date.');$clockEnabled=($_POST['fast_clock_enabled']??'0')==='1'?1:0;$clockRatio=(int)($_POST['fast_clock_ratio']??4);if(!in_array($clockRatio,ttFastClockRatios(),true))throw new RuntimeException('Choose a supported Fast Clock ratio.');$clockStart=ttFastClockNormalizeStart((string)($_POST['fast_clock_start_time']??'08:00'));$stmt=$pdo->prepare('INSERT INTO operating_sessions(railroad_id,created_by_user_id,session_number,session_name,operating_date,notes,fast_clock_enabled,fast_clock_start_minutes,fast_clock_ratio,fast_clock_base_model_seconds) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->execute([(int)$railroad['id'],(int)$_SESSION['user_id'],$number,$name?:null,$date,substr(trim((string)($_POST['notes']??'')),0,5000),$clockEnabled,$clockStart,$clockRatio,$clockStart*60]);$id=(int)$pdo->lastInsertId();$pdo->commit();header('Location: session_edit.php?id='.$id);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$stmt=$pdo->prepare("SELECT s.*,COUNT(a.id) assignment_count,SUM(a.status='completed') completed_count FROM operating_sessions s LEFT JOIN operation_assignments a ON a.session_id=s.id AND a.railroad_id=s.railroad_id AND a.status<>'cancelled' WHERE s.railroad_id=? GROUP BY s.id ORDER BY s.operating_date DESC,s.id DESC");$stmt->execute([(int)$railroad['id']]);$sessions=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<?php include '../includes/header.php';?><title>Operating Sessions</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="tt-eyebrow">Operations</p><h1>Operating Sessions</h1><p class="text-muted">Saved operating events with one or more work assignments.</p></div><button class="btn btn-primary" data-bs-toggle="collapse" data-bs-target="#newSession">New Session</button></div>
<?php if(isset($error)):?><div class="alert alert-danger"><?=ttHtml($error)?></div><?php endif;?><div class="collapse mb-4" id="newSession"><div class="card card-body"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><div class="col-md-5"><label class="form-label">Session Name <span class="text-muted">(optional)</span></label><input class="form-control" name="session_name" maxlength="120"></div><div class="col-md-3"><label class="form-label">Operating Date</label><input class="form-control" type="date" name="operating_date" value="<?=date('Y-m-d')?>" required></div><?php if(!empty($modules['fast_clock'])):?><div class="col-12"><div class="form-check"><input type="hidden" name="fast_clock_enabled" value="0"><input class="form-check-input" type="checkbox" name="fast_clock_enabled" value="1" id="newFastClock"><label class="form-check-label" for="newFastClock">Enable Fast Clock</label></div></div><div class="col-sm-6 col-md-3"><label class="form-label">Fast Clock Start</label><input class="form-control" type="time" name="fast_clock_start_time" value="08:00" required></div><div class="col-sm-6 col-md-3"><label class="form-label">Ratio</label><select class="form-select" name="fast_clock_ratio"><?php foreach([1,2,4,6,8,10] as $ratio):?><option value="<?=$ratio?>" <?=$ratio===4?'selected':''?>><?=$ratio?>:1</option><?php endforeach;?></select></div><?php endif;?><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"></textarea></div><div><button class="btn btn-success">Create Session</button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Session</th><th>Date</th><th>Assignments</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($sessions as $session):?><tr><td><a href="session_edit.php?id=<?=(int)$session['id']?>"><strong><?=ttHtml($session['session_number'])?></strong></a><div class="small text-muted"><?=ttHtml($session['session_name'])?></div></td><td><?=ttHtml($session['operating_date'])?></td><td><?=(int)$session['assignment_count']?></td><td><span class="badge tt-status-<?=ttHtml($session['status'])?>"><?=ttHtml(ttOperationsStatusLabel($session['status'],'session'))?></span></td><td><?=ttHtml($session['updated_at'])?></td></tr><?php endforeach;?><?php if(!$sessions):?><tr><td colspan="5" class="text-center text-muted py-5">Create the first operating session.</td></tr><?php endif;?></tbody></table></div></div></section></div><?php include '../includes/footer.php';?>
